      "id": "DMSR-9242",
      "title": "Data Availability",
      "text": "All raw data used to generate any public data product (raw exposures, calibration frames, telemetry, conﬁguration metadata, etc.) shall be kept and made available for download."
    },
    {
      "id": "DMSR-1753",
      "title": "Measurements in catalogs",
      "text": "All catalogs shall record source measurements in ﬂux units."
    },
    {
      "id": "DMSR-6573",
      "title": "Computing Derived Quantities",
      "text": "Common derived quantities shall be made available to end-users by either providing pre-computed columns or providing functions that can be used dynamically in queries. These should at least include the ability to calculate the reduced chi-squared of ﬁtted models and make it as easy as possible to calculate color-color diagrams."
    },
    {
      "id": "DMSR-5822",
      "title": "Denormalizing Database Tables",
      "text": "The database tables shall contain views presented to the users that will be appropriately denormalized for ease of use."
    },
    {
      "id": "DMSR-8509",
      "title": "Maximum Likelihood Values and Covariances",
      "text": "Quantities delivered by all measurement algorithms shall include maximum likelihood values and covariances."
    }
